306	// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
307	//
308	// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
309	// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
310	// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
311	// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
312	// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
313	//
314	// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
315	// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
316	// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
317	// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
318	// 部分恢复的钱包。任一账户的可用余额加上该账户在所有策略下仍处于已预留
319	// 状态的费用之和超出 int64 上限时同样拒绝（即使各请求、各策略金额分别
320	// 合法）：否则取消或预留超时的退回会使余额越界；校验在恢复时的到期
321	// 自动退回之前完成，预留尚未到期也当场拒绝。恢复出的钱包与原钱包、同一
322	// 备份恢复出的其他钱包互不影响。
323	func Restore(data []byte) (*Wallet, error) {
324		if len(bytes.TrimSpace(data)) == 0 {
325			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
326		}
327	
328		var b backupV1
329		dec := json.NewDecoder(bytes.NewReader(data))
330		if err := dec.Decode(&b); err != nil {
331			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
332		}
333		// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
334		if _, err := dec.Token(); err != io.EOF {
335			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
336		}
337		if b.Version != backupVersion {
338			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
339		}
340	
341		w := New()
342		if err := w.restoreLocked(&b); err != nil {
343			return nil, err
344		}
345		return w, nil
346	}
347	
348	// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
349	// 便于确定性地验证恢复时的到期处理。
350	func restoreAt(data []byte, now time.Time) (*Wallet, error) {
351		if len(bytes.TrimSpace(data)) == 0 {
352			return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
353		}
354		var b backupV1
355		dec := json.NewDecoder(bytes.NewReader(data))
356		if err := dec.Decode(&b); err != nil {
357			return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
358		}
359		if _, err := dec.Token(); err != io.EOF {
360			return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
361		}
362		if b.Version != backupVersion {
363			return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
364		}
365		w := New()
366		w.now = func() time.Time { return now }
367		if err := w.restoreLocked(&b); err != nil {
368			return nil, err
369		}
370		return w, nil
371	}
372	
373	// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
374	// 绝不会拿到部分恢复的钱包。
375	func (w *Wallet) restoreLocked(b *backupV1) error {
376		// ---- 账户 ----
377		if b.Accounts == nil {
378			return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
379		}
380		accountIDs := make(map[string]struct{}, len(b.Accounts))
381		reservedByAccount := make(map[string]int64)
382		for i, a := range b.Accounts {
383			if a.ID == "" {
384				return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
385			}
386			if _, dup := accountIDs[a.ID]; dup {
387				return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
388			}
389			if a.Available < 0 {
390				return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
391			}
392			if a.Reserved < 0 {
393				return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
394			}
395			accountIDs[a.ID] = struct{}{}
396			w.accounts[a.ID] = &account{
397				id:        a.ID,
398				available: a.Available,
399				reserved:  a.Reserved,
400				createdAt: a.CreatedAt.std(),
401			}
402		}
403	
404		// ---- 会话 ----
405		if b.Sessions == nil {
406			return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
407		}
408		sessionByID := make(map[string]*session, len(b.Sessions))
409		for i, s := range b.Sessions {
410			if s.ID == "" {
411				return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
412			}
413			if _, dup := sessionByID[s.ID]; dup {
414				return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
415			}
416			if s.AccountID == "" || s.DeviceID == "" {
417				return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
418			}
419			if _, ok := accountIDs[s.AccountID]; !ok {
420				return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
421			}
422			sess := &session{
423				id:        s.ID,
424				accountID: s.AccountID,
425				deviceID:  s.DeviceID,
426				expiresAt: s.ExpiresAt.std(),
427				revoked:   s.Revoked,
428				createdAt: s.CreatedAt.std(),
429			}
430			sessionByID[s.ID] = sess
431			w.sessions[s.ID] = sess
432		}
433	
434		// ---- 策略 ----
435		if b.Policies == nil {
436			return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
437		}
438		policyByID := make(map[string]*policy, len(b.Policies))
439		for i, p := range b.Policies {
440			if p.ID == "" {
441				return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
442			}
443			if _, dup := policyByID[p.ID]; dup {
444				return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
445			}
446			if err := validatePolicyParams(p); err != nil {
447				return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
448			}
449			if _, ok := accountIDs[p.PayerAccountID]; !ok {
450				return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
451			}
452			allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
453			for j, id := range p.AllowedAccountIDs {
454				if id == "" {
455					return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
456				}
457				if _, ok := accountIDs[id]; !ok {
458					return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
459				}
460				if _, dup := allowed[id]; dup {
461					return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
462				}
463				allowed[id] = struct{}{}
464			}
465			if p.ReservedTotal < 0 || p.SpentTotal < 0 {
466				return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
467			}
468			po := &policy{
469				id:                   p.ID,
470				payerAccountID:       p.PayerAccountID,
471				allowedAccounts:      allowed,
472				operation:            p.Operation,
473				payee:                p.Payee,
474				startsAt:             p.StartsAt.std(),
475				endsAt:               p.EndsAt.std(),
476				maxPerRequest:        p.MaxPerRequest,
477				maxTotal:             p.MaxTotal,
478				approvalThreshold:    p.ApprovalThreshold,
479				approvalWait:         p.ApprovalWait.std(),
480				maxReserveDuration:   p.MaxReserveDuration.std(),
481				reservedTotal:        p.ReservedTotal,
482				spentTotal:           p.SpentTotal,
483				deactivated:          p.Deactivated,
484				deactivatedAt:        p.DeactivatedAt.std(),
485				deactivatorAccountID: p.DeactivatorAccountID,
486				deactivateReason:     p.DeactivateReason,
487			}
488			// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
489			// 存在；未停用不得携带任何停用记录。
490			if po.deactivated {
491				if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
492					return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
493				}
494				if po.deactivatorAccountID != "" {
495					if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
496						return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
497					}
498				}
499			} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
500				return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
501			}
502			policyByID[p.ID] = po
503			w.policies[p.ID] = po
504		}
505	
506		// ---- 请求 ----
507		if b.Requests == nil {
508			return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
509		}
510		reqKeys := make(map[requestKey]struct{}, len(b.Requests))
511		reservedSumByPolicy := make(map[string]int64)
512		spentSumByPolicy := make(map[string]int64)
513		for i, r := range b.Requests {
514			if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
515				return err
516			}
517			key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
518			if _, dup := reqKeys[key]; dup {
519				return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
520			}
521			reqKeys[key] = struct{}{}
522	
523			state := RequestState(r.State)
524			if state < RequestReserved || state > RequestReservationExpired {
525				return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
526			}
527			if r.EstimatedFee <= 0 {
528				return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
529			}
530			if r.ActualFee < 0 {
531				return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
532			}
533			if r.ReserveDuration.std() < 0 {
534				return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
535			}
536	
537			req := &request{
538				policyID:          r.PolicyID,
539				requestID:         r.RequestID,
540				accountID:         r.AccountID,
541				payerAccountID:    r.PayerAccountID,
542				sessionID:         r.SessionID,
543				operation:         r.Operation,
544				payee:             r.Payee,
545				estimatedFee:      r.EstimatedFee,
546				actualFee:         r.ActualFee,
547				state:             state,
548				createdAt:         r.CreatedAt.std(),
549				settledAt:         r.SettledAt.std(),
550				waitDeadline:      r.WaitDeadline.std(),
551				reservedAt:        r.ReservedAt.std(),
552				reserveDuration:   r.ReserveDuration.std(),
553				reserveDeadline:   r.ReserveDeadline.std(),
554				reserveExpiredAt:  r.ReserveExpiredAt.std(),
555				decidedAt:         r.DecidedAt.std(),
556				approverAccountID: r.ApproverAccountID,
557				rejectReason:      r.RejectReason,
558			}
559			if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
560				return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
561			}
562			w.requests[key] = req
563	
564			// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
565			// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
566			if state == RequestReserved {
567				sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
568				if !ok {
569					return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
570				}
571				reservedByAccount[req.payerAccountID] = sum
572				sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
573				if !ok {
574					return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
575				}
576				reservedSumByPolicy[req.policyID] = sum
577			}
578			if state == RequestSettled {
579				sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
580				if !ok {
581					return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
582				}
583				spentSumByPolicy[req.policyID] = sum
584			}
585		}
586	
587		// ---- 账户预留余额 == 已预留请求预估费用之和 ----
588		for id, acc := range w.accounts {
589			if got, want := acc.reserved, reservedByAccount[id]; got != want {
590				return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
591			}
592		}
593	
594		// ---- 可用余额 + 现存预留不得超过 int64 上限 ----
595		// 取消或预留超时会把预留全额退回可用余额：合计一旦超出 MaxInt64，
596		// 退回时余额就会越界变负。reservedByAccount 按出资账户汇总该账户在
597		// 所有策略下仍处于已预留状态的费用（待审批不冻结费用，已结算、已取消、
598		// 已预留超时的费用不再占用预留，故均不计入）。本检查必须在恢复时的
599		// 到期自动退回之前完成，使“恢复即超时退款”的备份也不能蒙混过关；
600		// 合计恰好等于上限合法（随后退回恰好得到上限金额）。
601		for id, acc := range w.accounts {
602			if _, ok := addInt64(acc.available, reservedByAccount[id]); !ok {
603				return fmt.Errorf("%w: account %q available %d plus reserved %d overflows int64", ErrBackupInvalid, id, acc.available, reservedByAccount[id])
604			}
605		}
606	
607		// ---- 策略预留总额/已花费总额 == 请求求和 ----
608		for id, p := range policyByID {
609			if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
610				return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
611			}
612			if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
613				return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
614			}
615		}
616	
617		// ---- 账本 ----
618		if b.Ledger == nil {
619			return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
620		}
621		w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
622		for i, e := range b.Ledger {
623			kind := LedgerKind(e.Kind)
624			if kind < LedgerReserve || kind > LedgerReservationExpiration {
625				return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
626			}
627			if e.Amount < 0 {
628				return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
629			}
630			// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
631			// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
632			// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
633			// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
634			// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
635			if e.PolicyID != "" {
636				if _, ok := policyByID[e.PolicyID]; !ok {
637					return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
638				}
639			}
640			w.ledger = append(w.ledger, LedgerEntry{
641				Kind:      kind,
642				AccountID: e.AccountID,
643				RequestID: e.RequestID,
644				PolicyID:  e.PolicyID,
645				Amount:    e.Amount,
646				Reason:    e.Reason,
647				At:        e.At.std(),
648			})
649		}
650	
651		// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
652		// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
653		// 两类记录均按各自截止时刻排序后追加到账本末尾。
654		now := w.now()
655		w.expireReservationsLocked(now)
656		w.expirePendingApprovalsLocked(now)
657		return nil
658	}
659	
660	// validatePolicyParams 校验策略条件与限额参数，规则与 SavePolicy 一致。
661	func validatePolicyParams(p policyBackupV1) error {
662		if p.Operation == "" || p.Payee == "" {
663			return errors.New("operation and payee are required")
664		}
665		if p.MaxPerRequest <= 0 || p.MaxTotal <= 0 {
666			return errors.New("limits must be positive")
667		}
668		if p.ApprovalThreshold < 0 {
669			return errors.New("approval threshold must not be negative")
670		}
671		if p.ApprovalThreshold > 0 {
672			if p.ApprovalThreshold > p.MaxPerRequest {
673				return fmt.Errorf("approval threshold %d exceeds per-request limit %d", p.ApprovalThreshold, p.MaxPerRequest)
674			}
675			if p.ApprovalWait <= 0 {
676				return errors.New("approval wait must be positive when approval is enabled")
677			}
678		}
679		if p.ApprovalWait < 0 || p.MaxReserveDuration < 0 {
680			return errors.New("durations must not be negative")
681		}
682		if !p.StartsAt.std().Before(p.EndsAt.std()) {
683			return errors.New("starts-at must be before ends-at")
684		}
685		if p.PayerAccountID == "" || len(p.AllowedAccountIDs) == 0 {
686			return errors.New("payer account and at least one allowed account are required")
687		}
688		return nil
689	}
690	
691	// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
692	// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
693	func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
694		where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
695		if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
696			return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
697		}
698		if _, ok := accounts[r.AccountID]; !ok {
699			return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
700		}
701		if _, ok := accounts[r.PayerAccountID]; !ok {
702			return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
703		}
704		sess, ok := sessions[r.SessionID]
705		if !ok {
706			return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
707		}
708		// 申请会话必须属于使用账户。
709		if sess.accountID != r.AccountID {
710			return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
711		}
712		p, ok := policies[r.PolicyID]
713		if !ok {
714			return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
715		}
716		// 请求出资账户必须与策略出资账户一致。
717		if r.PayerAccountID != p.payerAccountID {
718			return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
719		}
720		if _, ok := p.allowedAccounts[r.AccountID]; !ok {
721			return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
722		}
723		return nil
724	}
725	
726	// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
727	// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
728	// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
729	// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
730	func validateReserveTiming(r *request) error {
731		if r.reserveDuration < 0 {
732			return errors.New("reserve duration must not be negative")
733		}
734		if r.reserveDuration > 0 {
735			if r.reservedAt.IsZero() {
736				return errors.New("reserve duration set but reserved_at is missing")
737			}
738			want := r.reservedAt.Add(r.reserveDuration)
739			if !r.reserveDeadline.Equal(want) {
740				return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
741			}
742		} else if !r.reserveDeadline.IsZero() {
743			return errors.New("reserve deadline set while reserve duration is zero")
744		}
745		return nil
746	}
747	
748	// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
749	// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
750	// 备份。sess 为该请求的申请会话。
751	func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
752		if r.createdAt.IsZero() {
753			return errors.New("request missing created_at")
754		}
755		if r.operation == "" || r.payee == "" {
756			return errors.New("operation and payee are required")
757		}
758		if r.operation != p.operation || r.payee != p.payee {
759			return fmt.Errorf("operation/payee do not match policy %q", p.id)
760		}
761		if r.estimatedFee > p.maxPerRequest {
762			return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
763		}
764		if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
765			return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
766		}
767		if r.actualFee > r.estimatedFee {
768			return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
769		}
770	
771		// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
772		// 只能来自待审批流程；其余请求只能直接预留。
773		approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
774		reservedOrigin := !r.reservedAt.IsZero()
775	
776		switch r.state {
777		case RequestReserved, RequestSettled, RequestReservationExpired:
778			// 这三类一定发生过预留。
779			if err := validateReservedOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
780				return err
781			}
782		case RequestPendingApproval, RequestRejected, RequestExpired:
783			// 这三类一定从未预留，且必须来自开启审批的策略。
784			if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
785				return err
786			}
787		case RequestCancelled:
788			// 取消可能来自待审批（从未预留）或已预留。
789			if reservedOrigin {
790				if err := validateReservedOrigin(r, p, approvalRequired, true); err != nil {
791					return err
792				}
793			} else {
794				if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
795					return err
796				}
797			}
798		default:
799			return fmt.Errorf("unknown state %d", r.state)
800		}
801	
802		switch r.state {
803		case RequestReserved:
804			// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
805			// 且不得已记录超时。
806			if err := validateReserveTiming(r); err != nil {
807				return err
808			}
809			if !r.reserveExpiredAt.IsZero() {
810				return errors.New("reserved request must not carry reserve-expired time")
811			}
812			if r.actualFee != 0 || !r.settledAt.IsZero() {
813				return errors.New("reserved request must not be settled")
814			}
815			if r.rejectReason != "" {
816				return errors.New("reserved request must not carry a reject reason")
817			}
818		case RequestSettled:
819			if r.settledAt.IsZero() {
820				return errors.New("settled request missing settled_at")
821			}
822			if !r.reserveExpiredAt.IsZero() {
823				return errors.New("settled request must not carry reserve-expired time")
824			}
825			if r.settledAt.Before(r.reservedAt) {
826				return errors.New("settled_at is before reserved_at")
827			}
828			if err := validateReserveTiming(r); err != nil {
829				return err
830			}
831			if r.rejectReason != "" {
832				return errors.New("settled request must not carry a reject reason")
833			}
834		case RequestCancelled:
835			if r.actualFee != 0 || !r.settledAt.IsZero() {
836				return errors.New("cancelled request must not be settled")
837			}
838			if !r.reserveExpiredAt.IsZero() {
839				return errors.New("cancelled request must not carry reserve-expired time")
840			}
841			if r.rejectReason != "" {
842				return errors.New("cancelled request must not carry a reject reason")
843			}
844			if reservedOrigin {
845				if err := validateReserveTiming(r); err != nil {
846					return err
847				}
848			} else {
849				// 待审批取消：决定时间必填。
850				if r.decidedAt.IsZero() {
851					return errors.New("cancelled-from-pending request missing decided_at")
852				}
853			}
854		case RequestPendingApproval:
855			// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
856			// min(提交+等待时长, 策略结束, 申请会话到期)。
857			if r.actualFee != 0 || !r.settledAt.IsZero() {
858				return errors.New("pending request must not be settled")
859			}
860			if r.waitDeadline.IsZero() {
861				return errors.New("pending request missing wait deadline")
862			}
863			if r.approverAccountID != "" {
864				return errors.New("pending request must not carry an approver")
865			}
866			if r.rejectReason != "" {
867				return errors.New("pending request must not carry a reject reason")
868			}
869			want := r.createdAt.Add(p.approvalWait)
870			if p.endsAt.Before(want) {
871				want = p.endsAt
872			}
873			if sess.expiresAt.Before(want) {
874				want = sess.expiresAt
875			}
876			if !r.waitDeadline.Equal(want) {
877				return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
878			}
879		case RequestRejected:
880			if r.decidedAt.IsZero() || r.rejectReason == "" {
881				return errors.New("rejected request missing decided_at or reason")
882			}
883		case RequestExpired:
884			if r.decidedAt.IsZero() {
885				return errors.New("expired request missing decided_at")
886			}
887			if r.rejectReason != "" {
888				return errors.New("expired request must not carry a reject reason")
889			}
890			// 惰性/停用过期的决定时刻不可能早于等待截止时刻。
891			if r.decidedAt.Before(r.waitDeadline) {
892				return errors.New("expired request decided before its wait deadline")
893			}
894		case RequestReservationExpired:
895			if r.reserveDuration <= 0 {
896				return errors.New("reservation-expired request must have a positive reserve duration")
897			}
898			if err := validateReserveTiming(r); err != nil {
899				return err
900			}
901			if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
902				return errors.New("reserve-expired-at must equal reserve deadline")
903			}
904			if r.actualFee != 0 || !r.settledAt.IsZero() {
905				return errors.New("reservation-expired request must not be settled")
906			}
907			if r.rejectReason != "" {
908				return errors.New("reservation-expired request must not carry a reject reason")
909			}
910		}
911		return nil
912	}
913	
914	// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
915	// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间）与费用/门槛
916	// 相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、已预留后
917	// 取消）统一适用：超门槛的必须经出资账户在预留时刻批准，未超门槛的直接
918	// 受理、不得携带批准人或决定时间。
919	func validateReservedOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
920		if !reservedOrigin {
921			return errors.New("request is in a reserved-origin state but missing reserved_at")
922		}
923		if r.reserveDuration != p.maxReserveDuration {
924			return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
925		}
926		if approvalRequired {
927			if r.approverAccountID != r.payerAccountID {
928				return errors.New("above-threshold request was reserved without payer approval")
929			}
930			if !r.decidedAt.Equal(r.reservedAt) {
931				return errors.New("approved request decided_at must equal reserved_at")
932			}
933		} else {
934			if r.approverAccountID != "" {
935				return errors.New("below-threshold request must not carry an approver")
936			}
937			if !r.decidedAt.IsZero() {
938				return errors.New("directly reserved request must not carry decided_at")
939			}
940		}
941		return nil
942	}
943	
944	// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
945	// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
946	func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
947		if reservedOrigin {
948			return errors.New("request is in a pending-origin state but carries reserved_at")
949		}
950		if !approvalRequired {
951			return errors.New("request is in an approval state although policy approval is not enabled for its fee")
952		}
953		if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
954			return errors.New("pending-origin request must not carry reserve timing")
955		}
956		return nil
957	}
958

