			a := m["accounts"].([]interface{})
			a[0].(map[string]interface{})["available"] = -1
		}},
		{"negative account reserved", func(m map[string]interface{}) {
			a := m["accounts"].([]interface{})
			a[0].(map[string]interface{})["reserved"] = -1
		}},
		{"negative ledger amount", func(m map[string]interface{}) {
