		}},
		{"application session belongs to another account", func(m map[string]interface{}) {
			// 找一条 u1 的请求，把它的会话改成属于 u2 的 s2。
			for _, r := range m["requests"].([]interface{}) {
				rm := r.(map[string]interface{})
				if rm["account_id"] == "u1" {
